select o_id, p_name,o_afterSales order_sort,o_state,op_id keyboarder,p_number,o_substation fenzhan from order_info_all



        AND o_afterSales LIKE CONCAT('%',#{o_sort},'%')


        AND o_date>#{startdate}


        AND o_date<#{finishdate}

mapper.insert:
INSERT INTO shangpin_diaobo (d_id,chuku_kufang,ruku_kufang, p_sort,p_name,unit,o_date,diaobo_num)
SELECT o_id,'中心库房',o_substation,p_type,p_name,o_state,o_date,p_amount
FROM order_info_all where o_state='可调度';

mapper.select:
select Chuku_order.o_id,order_sort,o_state,o_date,keyboarder,p_name,p_number,o_receiver,o_address,o_recPhone, o_postcode,substation,o_invoice,remark,station
from order_info_all, Chuku_order
where order_info_all.o_id = Chuku_order.o_id and Chuku_order.o_id=#{id}

